package com.example.zerohaus.Util

/**
 * Textos de la app en el idioma indicado (nombre tal como aparece en Ajustes). Por defecto, español.
 */
fun getCadenas(idioma: String): AppCadenas = when (idioma) {
    "English"    -> english
    "Català"     -> catala
    "Euskara"    -> euskara
    "Galego"     -> galego
    "Português"  -> portugues
    "Français"   -> francais
    "Deutsch"    -> deutsch
    "Italiano"   -> italiano
    "العربية"    -> arabe
    "中文"        -> chino
    "Română"     -> rumano
    "Nederlands" -> neerlandes
    "Polski"     -> polaco
    else         -> espanol
}

